embeddings = {
    'king': [0.9, 0.1],
    'man': [0.8, 0.0],
    'queen': [0.9, 0.8],
    'woman': [0.8, 0.9]
}
def cosine_similarity(v1, v2):
    return sum(a*b for a,b in zip(v1,v2)) / (sum(a*a for a in v1)**0.5 * sum(b*b for b in v2)**0.5)

print(f"Similarity (king, queen): {cosine_similarity(embeddings['king'], embeddings['queen']):.3f}")
